def bmi(weight, height):
    bmi = weight / (height ** 2)
    if bmi <= 18.5:
        return "Underweight"
    elif bmi <= 25.0:
        return "Normal"
    elif bmi <= 30.0:
        return "Overweight"
    else:
        return "Obese"

def greatest_distance(arr):
    index_map = {}
    max_distance = 0

    for i, num in enumerate(arr):
        if num in index_map:
            current_distance = i - index_map[num]
            max_distance = max(max_distance, current_distance)
        else:
            index_map[num] = i

    return max_distance

