class Solution:
    def numUniqueEmails(self, emails: List[str]) -> int:
        unique_emails = set()
        for email in emails:
            local, domain = email.split('@')
            local = local.split('+')[0].replace('.', '')
            unique_emails.add(local + '@' + domain)
        return len(unique_emails)

def interpreter(tape):
    data = [0]
    selector = 0
    output = ''

    for command in tape:
        if command == '>':
            selector += 1
            if selector >= len(data):
                continue
        elif command == '<':
            selector -= 1
            if selector < 0:
                continue
        elif command == '*':
            output += chr(data[selector])
        elif command == '+':
            data[selector] = (data[selector] + 1) % 256
        elif command == '-':
            data[selector] = (data[selector] - 1) % 256
        elif command == '/':
            data[selector] = 0
        elif command == '!':
            data.append(0)

    return output

def mn_lcm(m, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    lcm = 1
    for i in range(m, n + 1):
        lcm = lcm * i // gcd(lcm, i)
    return lcm

def getAllPrimeFactors(n):
    if not isinstance(n, int) or n <= 0:
        return []
    factors = []
    d = 2
    while d * d <= n:
        while (n % d) == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def getUniquePrimeFactorsWithCount(n):
    if not isinstance(n, int) or n <= 0:
        return [[], []]
    if n == 1:
        return [[1], [1]]
    factors = []
    powers = []
    d = 2
    while d * d <= n:
        count = 0
        while (n % d) == 0:
            count += 1
            n //= d
        if count > 0:
            factors.append(d)
            powers.append(count)
        d += 1
    if n > 1:
        factors.append(n)
        powers.append(1)
    return [factors, powers]

def getPrimeFactorPotencies(n):
    if not isinstance(n, int) or n <= 0:
        return []
    if n == 1:
        return [1]
    factors = []
    powers = []
    d = 2
    while d * d <= n:
        count = 0
        while (n % d) == 0:
            count += 1
            n //= d
        if count > 0:
            factors.append(d)
            powers.append(count)
        d += 1
    if n > 1:
        factors.append(n)
        powers.append(1)
    potencies = []
    for p in powers:
        potencies.append(p * factors[powers.index(p)])
    return potencies

def find_combinations(tuples):
    results = []
    for i in range(len(tuples)):
        for j in range(i+1, len(tuples)):
            for k in range(j+1, len(tuples)):
                results.append((tuples[i], tuples[j], tuples[k]))
    return results

